const cookieValue=name=>document.cookie.split(';').map(v=>v.trim()).find(v=>v.startsWith(`${name}=`))?.slice(name.length+1)||'';
function readableError(value,fallback='No se pudo completar la operación'){if(typeof value==='string'&&value.trim())return value;if(Array.isArray(value)){const messages=value.map(item=>readableError(item,'')).filter(Boolean);return messages.length?messages.join(' · '):fallback}if(value&&typeof value==='object'){if(typeof value.message==='string'&&value.message.trim())return value.message;if(typeof value.msg==='string'&&value.msg.trim())return value.msg;if(value.detail!==undefined)return readableError(value.detail,fallback)}return fallback}
const api=async(url,opt={})=>{const method=(opt.method||'GET').toUpperCase(),mutating=['POST','PUT','PATCH','DELETE'].includes(method),headers={'Content-Type':'application/json',...(mutating&&cookieValue('centro_csrf')?{'X-CSRF-Token':decodeURIComponent(cookieValue('centro_csrf'))}:{})};const r=await fetch(url,{credentials:'same-origin',headers,...opt});if(r.status===401&&!['/api/auth/login','/api/auth/google'].includes(url)){authUser=null;showLogin()}const raw=await r.text();let payload=null;if(raw)try{payload=JSON.parse(raw)}catch{}if(!r.ok){const generic=r.status>=500?`El servidor no pudo completar la operación (${r.status})`:`Error de operación (${r.status})`;throw new Error(readableError(payload?.detail,generic))}if(!raw)return null;if(payload===null)throw new Error('El servidor respondió con un formato inesperado');return payload};
function isoDate(value){const d=value instanceof Date?value:new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function mondayISO(value=new Date()){const d=value instanceof Date?new Date(value.getTime()):new Date(`${value}T12:00:00`);d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return isoDate(d)}
function shiftISO(value,days){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()+days);return isoDate(d)}
