window.toast=message=>{const t=document.getElementById('toast');t.textContent=readableError(message,'Ocurrió un error inesperado');t.className='show';setTimeout(()=>t.className='',3000)};
function closeTransientMenus(event){
  const target=event.target instanceof Element?event.target:null;
  if(!target?.closest('.wfm-dropdown-wrap')){
    document.querySelectorAll('.wfm-dropdown-menu.show').forEach(menu=>{
      menu.classList.remove('show');
      menu.previousElementSibling?.setAttribute('aria-expanded','false');
    });
  }
  const supervisionMenu=document.getElementById('supervision-items');
  if(supervisionMenu&&!target?.closest('[data-supervision-menu]')){
    supervisionMenu.hidden=true;
    state.supervisionOpen=false;
    document.getElementById('supervision-toggle')?.setAttribute('aria-expanded','false');
  }
}
document.addEventListener('click',closeTransientMenus);
const sidebarToggle=document.getElementById('sidebar-toggle');
const setSidebarCollapsed=collapsed=>{
  document.body.classList.toggle('sidebar-collapsed',collapsed);
  sidebarToggle?.setAttribute('aria-expanded',String(!collapsed));
  sidebarToggle?.setAttribute('aria-label',collapsed?'Expandir menú':'Contraer menú');
  sidebarToggle?.setAttribute('title',collapsed?'Expandir menú':'Contraer menú');
  localStorage.setItem('sidebarCollapsed',String(collapsed));
  window.setTimeout(()=>window.quoteLeafletMap?.invalidateSize({pan:false}),220);
};
