 const report=can('reports.export')?`<button class="row-action" onclick="downloadOperationalReport('schedules',new URLSearchParams('${scheduleReportParams().toString()}'))">Descargar reporte</button>`:'';
 const columns=[['Fecha',r=>`<strong>${esc(scheduleDateLabel(r.schedule_date))}</strong><small class="schedule-week-label">Semana ${esc(r.week_start)}</small>`],['Persona','display_name'],['Rol',r=>esc(r.role_name)],['Turno',r=>esc(r.shift_name)],['Horario',r=>`${esc(scheduleTimeLabel(r.start_time))} a ${esc(scheduleTimeLabel(r.end_time))}`],['Notas',r=>esc(r.notes||'—')]];
 const result=state.scheduleView==='week'?scheduleWeekGrid(rows,people):table(columns,rows,()=>'', 'No hay horarios para el período y filtros seleccionados.');
