function normalizedTransferStatus(status){return ({PENDIENTE:'SIN_ASIGNAR',CONFIRMADO:'ASIGNADO',COMPLETADO:'FINALIZADO'}[status]||status||'SIN_ASIGNAR')}
function transferStatusSelect(r){const current=normalizedTransferStatus(r.status);if(!can('transfers.manage'))return badge(current);return `<details class="status-dropdown"><summary class="status-chip ${esc(current)}">${esc(statusLabel(current))}</summary><div class="status-options"><button class="status-option SIN_ASIGNAR" onclick="changeTransferStatus(${r.id},'SIN_ASIGNAR')">Sin asignar</button><button class="status-option ASIGNADO" onclick="changeTransferStatus(${r.id},'ASIGNADO')">Asignado</button><button class="status-option FINALIZADO" onclick="changeTransferStatus(${r.id},'FINALIZADO')">Finalizado</button></div></details>`}
function transferRowClass(r){const t=(r.transfer_type||'').toLowerCase();return `transfer-row ${t.includes('depósito')||t.includes('deposito')?'transfer-deposit':t.includes('directo')?'transfer-direct':t.includes('mercosur')?'transfer-mercosur':'transfer-long'}`}
