function transferColumns(){return [['Fecha','scheduled_date'],['Hora',r=>esc(r.scheduled_time?.slice(0,5)||'—')],['Tarea',r=>taskLink(r.task_number)],['Desde','origin'],['Hacia','destination'],['Prestador',r=>esc(r.provider||'Sin asignar')],['Planifica','planner'],['Estado',r=>transferStatusSelect(r)],['Acciones',r=>transferActions(r)]]}
function transferActions(r){if(!can('transfers.manage'))return '—';return `<div class="action-cluster"><button class="row-action edit-transfer" onclick="openEditTransfer(${r.id})">✎ Editar</button><details class="more-menu"><summary aria-label="Más opciones">•••</summary><div class="more-menu-pop"><button onclick="duplicateTransfer(${r.id})">Duplicar</button><button class="delete-option" onclick="deleteTransfer(${r.id})">Eliminar</button></div></details></div>`}
function groupedTransfers(rows){if(!rows.length)return `<div class="panel empty">No hay programados para los filtros seleccionados.</div>`;const groups=[['Traslados largos',r=>!/(depósito|deposito|directo|mercosur)/i.test(r.transfer_type||'')],['Traslados a depósito',r=>/(depósito|deposito)/i.test(r.transfer_type||'')],['Traslados directos',r=>/directo/i.test(r.transfer_type||'')],['Mercosur',r=>/mercosur/i.test(r.transfer_type||'')]];return groups.map(([name,test])=>{const items=rows.filter(test);return items.length?`<section class="transfer-group"><div class="group-heading"><div><h2>${name}</h2><span>${items.length} ${items.length===1?'programado':'programados'}</span></div></div>${table(transferColumns(),items,transferRowClass)}</section>`:''}).join('')}
