$('#entity-form').addEventListener('submit',async e=>{e.preventDefault();const type=e.target.dataset.type,form=new FormData(e.target);try{if(type==='role'){await api(`/api/roles/${e.target.dataset.roleId}/permissions`,{method:'PATCH',body:JSON.stringify({permissions:form.getAll('permissions')})});$('#modal').close();toast('Permisos actualizados');return render()}const body=Object.fromEntries(form);if(type==='role_create'){const created=await api('/api/settings/roles',{method:'POST',body:JSON.stringify(body)});state.selectedRole=created.id;$('#modal').close();toast('Rol creado');return render()}if(type==='user'){body.role_id=Number(body.role_id);await api('/api/settings/users',{method:'POST',body:JSON.stringify(body)});$('#modal').close();toast('Usuario creado');return render()}if(type==='user_edit'){body.role_id=Number(body.role_id);body.active=form.has('active');await api(`/api/users/${e.target.dataset.userId}`,{method:'PATCH',body:JSON.stringify(body)});$('#modal').close();toast('Usuario actualizado');return render()}if(type==='schedule'||type==='schedule_edit'){body.user_id=Number(body.user_id);body.start_time=body.start_time||null;body.end_time=body.end_time||null;body.notes=body.notes||null;const endpoint=type==='schedule_edit'?`/api/schedules/${e.target.dataset.scheduleId}`:'/api/schedules';await api(endpoint,{method:type==='schedule_edit'?'PATCH':'POST',body:JSON.stringify(body)});$('#modal').close();toast(type==='schedule_edit'?'Horario actualizado':'Horario configurado');return render()}if(type==='notice_comment'){const r=window.noticeCache.find(x=>x.id===Number(e.target.dataset.noticeId));await api(`/api/notices/${r.id}/status`,{method:'PATCH',body:JSON.stringify({status:r.status,actor:currentUser,managed_by:r.managed_by||null,comments:body.comments||null})});$('#modal').close();toast('Comentario guardado');return render()}Object.keys(body).forEach(k=>{if(body[k]==='')body[k]=null});if(type==='transfer_edit'){await api(`/api/transfers/${e.target.dataset.transferId}`,{method:'PATCH',body:JSON.stringify(body)});$('#modal').close();toast('Programado actualizado');return render()}if(body.minutes)body.minutes=Number(body.minutes);if(type==='notice'){body.communicated_by=currentUser;body.status='PENDIENTE'}if(type==='delay'){body.agent=currentUser;body.status='VIGENTE'}if(type==='transfer'){body.planner=currentUser;body.status='SIN_ASIGNAR'}const endpoint={notice:'notices',delay:'delays',transfer:'transfers'}[type];await api(`/api/${endpoint}`,{method:'POST',body:JSON.stringify(body)});$('#modal').close();toast('Registro guardado correctamente');render()}catch(x){toast(x.message)}});
