function openNoticeComment(id){const r=window.noticeCache.find(x=>x.id===id);if(!r)return;$('#modal-title').textContent=`Comentario de gestión${r.task_number?' · Tarea '+r.task_number:''}`;$('#entity-form').dataset.type='notice_comment';$('#entity-form').dataset.noticeId=id;$('#fields').innerHTML=`<div class="field full"><label>Comentario</label><textarea name="comments" rows="7" placeholder="Escribí el seguimiento o resultado de la gestión...">${esc(r.comments||'')}</textarea></div>`;$('#modal').showModal()}
