function permissionHint(key){const hints={'dashboard.view':'Acceso al panel de indicadores','delays.view':'Puede consultar demoras activas e históricas','delays.create':'Puede informar una nueva afectación','delays.normalize':'Puede retirar una demora de la vista activa','notices.view':'Puede consultar avisos del equipo','notices.create':'Puede dejar un nuevo aviso','notices.manage':'Puede asignar, comentar y cerrar avisos','transfers.view':'Puede consultar servicios programados','transfers.create':'Puede registrar servicios programados','transfers.manage':'Puede editar programados y cambiar su estado','schedules.view':'Puede consultar horarios por semana y persona','schedules.manage':'Puede crear, editar y eliminar horarios','quotes.view':'Puede consultar el cotizador y su historial','quotes.create':'Puede calcular y guardar nuevas cotizaciones','standards.view':'Puede consultar referencias de arribo','audit.view':'Puede consultar el registro de auditoría','settings.manage':'Puede cambiar usuarios, roles y permisos'};return esc(hints[key]||'Permiso del sistema')}
