function openUserForm(){const roles=window.roleCache||[];$('#modal-title').textContent='Crear usuario corporativo';$('#entity-form').dataset.type='user';$('#fields').innerHTML=`<div class="field"><label>Nombre visible</label><input name="display_name" required></div><div class="field"><label>Correo corporativo</label><input name="email" type="email" placeholder="nombre@portoservicios.com.uy" pattern=".+@portoservicios\\.com\\.uy" required></div><div class="field"><label>Usuario alternativo (opcional)</label><input name="username" placeholder="Se usará la parte anterior al @"></div>${passwordField('password','Contraseña alternativa (opcional)','Mínimo 12 caracteres')}<div class="field"><label>Rol</label><select name="role_id">${roles.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></div><div class="field full"><small>El usuario puede ingresar con su correo o usuario y esta contraseña local.</small></div>`;$('#modal').showModal()}
function openRoleForm(){$('#modal-title').textContent='Crear rol personalizado';$('#entity-form').dataset.type='role_create';$('#fields').innerHTML=`<div class="field full"><label>Nombre del rol</label><input name="name" required placeholder="Ej.: Coordinador nocturno"></div><div class="field full"><label>Descripción (opcional)</label><textarea name="description" placeholder="Responsabilidad principal del rol"></textarea></div><div class="field full"><small>El rol se creará sin permisos. Después podrás habilitarlos desde esta misma pestaña.</small></div>`;$('#modal').showModal()}
function openEditTransfer(id){const r=window.transferCache.find(x=>x.id===id);if(!r)return;$('#modal-title').textContent=`Editar programado ${esc(r.task_number)}`;$('#entity-form').dataset.type='transfer_edit';$('#entity-form').dataset.transferId=id;const types=['Traslado Largo','Traslado Depósito','Traslado Directo','Mercosur'];$('#fields').innerHTML=`<div class="field"><label>Tarea</label><input name="task_number" value="${esc(r.task_number)}" required></div><div class="field"><label>Tipo de traslado</label><select name="transfer_type">${types.map(t=>`<option ${t===r.transfer_type?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Fecha</label><input name="scheduled_date" type="date" value="${esc(r.scheduled_date)}" required></div><div class="field"><label>Hora</label><input name="scheduled_time" type="time" value="${esc(r.scheduled_time?.slice(0,5)||'')}"></div><div class="field"><label>Desde</label><input name="origin" value="${esc(r.origin)}" required></div><div class="field"><label>Hacia</label><input name="destination" value="${esc(r.destination)}" required></div><div class="field"><label>Prestador / Auxiliador</label><input name="provider" value="${esc(r.provider||'')}"></div><div class="field full"><label>Comentarios</label><textarea name="comments">${esc(r.comments||'')}</textarea></div>`;$('#modal').showModal()}
function openEditUser(id){const u=window.userCache.find(x=>x.id===id),roles=window.roleCache;$('#modal-title').textContent=`Editar usuario: ${esc(u.username)}`;$('#entity-form').dataset.type='user_edit';$('#entity-form').dataset.userId=id;$('#fields').innerHTML=`<div class="field"><label>Nombre visible</label><input name="display_name" value="${esc(u.display_name)}" required></div><div class="field"><label>Correo corporativo</label><input name="email" type="email" value="${esc(u.email||'')}" placeholder="nombre@portoservicios.com.uy" pattern=".+@portoservicios\\.com\\.uy" required></div><div class="field"><label>Rol</label><select name="role_id">${roles.map(r=>`<option value="${r.id}" ${r.id===u.role_id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>${passwordField('password','Nueva contraseña alternativa (opcional)','Dejar vacío para conservar la actual')}<div class="field full"><label><input name="active" type="checkbox" ${u.active?'checked':''}> Usuario activo</label></div><div class="field full"><small>${u.google_linked?'Cuenta de Google vinculada. Si cambia el correo, deberá vincularse nuevamente.':'La cuenta de Google se vinculará automáticamente en el primer ingreso.'}</small></div>`;$('#modal').showModal()}
async function editRole(id){const role=window.roleCache.find(r=>r.id===id),permissions=window.permissionCache;$('#modal-title').textContent=`Permisos: ${role.name}`;$('#entity-form').dataset.type='role';$('#entity-form').dataset.roleId=id;$('#fields').innerHTML=permissions.map(p=>`<label class="field"><span><input type="checkbox" name="permissions" value="${esc(p.key)}" ${role.permissions.includes(p.key)?'checked':''}> ${esc(p.label)}</span></label>`).join('');$('#modal').showModal()}
const DELAY_DEPARTMENTS=['ARTIGAS','CANELONES','CERRO LARGO','COLONIA','DURAZNO','FLORES','FLORIDA','LAVALLEJA','MALDONADO','MONTEVIDEO','PAYSANDÚ','RÍO NEGRO','RIVERA','ROCHA','SALTO','SAN JOSÉ','SORIANO','TACUAREMBÓ','TREINTA Y TRES'];
const DELAY_SERVICES=['GRÚA','ML','SINIESTROS'];
function clearDelayFilters(){state.delayView='active';state.delayFrom='';state.delayTo='';state.delayDepartment='';state.delayService='';state.delaySearch='';render()}
function delayFilterParams(){const params=new URLSearchParams();if(state.delayFrom)params.set('date_from',state.delayFrom);if(state.delayTo)params.set('date_to',state.delayTo);if(state.delayView==='active')params.set('status','VIGENTE');if(state.delayView==='history')params.set('status','NORMALIZADO');if(state.delayDepartment)params.set('department',state.delayDepartment);if(state.delayService)params.set('service',state.delayService);if(state.delaySearch)params.set('q',state.delaySearch);return params}
function delayMatches(row){if(state.delayView==='active'&&row.status!=='VIGENTE')return false;if(state.delayView==='history'&&row.status!=='NORMALIZADO')return false;const day=String(row.created_at||'').slice(0,10);if(state.delayFrom&&day<state.delayFrom)return false;if(state.delayTo&&day>state.delayTo)return false;if(state.delayDepartment&&normalizeDept(row.department)!==normalizeDept(state.delayDepartment))return false;if(state.delayService&&normalizeDept(row.service)!==normalizeDept(state.delayService))return false;if(state.delaySearch){const q=state.delaySearch.toLowerCase();return [row.service,row.department,row.zone,row.message,row.agent,row.created_at,row.normalized_at,fmt(row.created_at)].some(value=>String(value||'').toLowerCase().includes(q))}return true}
async function renderDelaysPage(){const allRows=await api('/api/delays');window.delayCache=allRows;const rows=allRows.filter(delayMatches),reportParams=delayFilterParams();const viewOptions=`<select onchange="state.delayView=this.value;render()"><option value="active" ${state.delayView==='active'?'selected':''}>Solo vigentes</option><option value="history" ${state.delayView==='history'?'selected':''}>Normalizadas / histórico</option><option value="all" ${state.delayView==='all'?'selected':''}>Todas</option></select>`;const filters=`<div class="panel filter-panel"><div class="toolbar"><div class="toolbar-left"><label>Desde <input type="date" value="${esc(state.delayFrom)}" onchange="state.delayFrom=this.value"></label><label>Hasta <input type="date" value="${esc(state.delayTo)}" onchange="state.delayTo=this.value"></label>${viewOptions}<select onchange="state.delayDepartment=this.value"><option value="">Todos los departamentos</option>${DELAY_DEPARTMENTS.map(department=>`<option value="${esc(department)}" ${state.delayDepartment===department?'selected':''}>${esc(department)}</option>`).join('')}</select><select onchange="state.delayService=this.value"><option value="">Todas las prestaciones</option>${DELAY_SERVICES.map(service=>`<option value="${esc(service)}" ${state.delayService===service?'selected':''}>${esc(service)}</option>`).join('')}</select><input class="wide-search" placeholder="Texto, zona, agente o fecha" value="${esc(state.delaySearch)}" oninput="state.delaySearch=this.value" onkeydown="if(event.key==='Enter')render()"><button class="row-action" onclick="render()">Aplicar filtros</button><button class="row-action" onclick="clearDelayFilters()">Limpiar</button></div></div></div>`;const bar=navToolbar(`<strong>${rows.length} zonas</strong>`,`${can('reports.export')?`<button class="row-action" onclick="downloadOperationalReport('delays',new URLSearchParams('${reportParams.toString()}'))">Descargar reporte</button>`:''}${can('delays.create')?'<button class="primary" onclick="openForm(\'delay\')">+ Registrar demora</button>':''}`);$('#content').innerHTML=bar+filters+table([['Registrada',r=>fmt(r.created_at)],['Estado',r=>badge(r.status)],['Prestación',r=>esc(r.service)],['Departamento',r=>`<strong>${esc(r.department)}</strong>`],['Zona afectada',r=>esc(r.zone)],['Indicación al cliente',r=>esc(r.message==='Margen de'&&r.minutes?`Margen de ${r.minutes} minutos`:r.message)],['Registró',r=>esc(r.agent)],['Acción',r=>r.status==='VIGENTE'&&can('delays.normalize')?`<button class="row-action danger" onclick="normalizeDelay(${r.id})">Marcar normalizada</button>`:'—']],rows,r=>r.status==='VIGENTE'?'active-delay':'','No hay demoras para los filtros seleccionados.')}
pages.delays=renderDelaysPage;
let timer;function renderDebounced(){clearTimeout(timer);timer=setTimeout(render,250)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.search='';render()});$('#supervision-toggle').onclick=()=>{state.supervisionOpen=!state.supervisionOpen;render()};$('#user-button').onclick=logout;
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});await completeLogin(result)}catch(err){$('#login-error').textContent=err.message}});
async function bootstrap(){try{authUser=await api('/api/auth/me');currentUser=authUser.display_name;render()}catch{showLogin()}}bootstrap();
